/**
 * Before first paint, re-applies the CSS that theme.client.ts cached for a customized theme,
 * so returning visitors don't see the default theme flash. The CSS was generated by
 * themeToCss() from a validated theme; it is set via textContent, never parsed as HTML.
 * Its selectors get one extra `:root` so it outranks the live (server-default) style
 * until theme.client.ts removes it.
 */
const PREPAINT_SCRIPT = `try{var c=localStorage.getItem('${THEME_CSS_STORAGE_KEY}');`
  + `if(c&&!/[<>]|url\\(|@import|expression/i.test(c)){var s=document.createElement('style');`
  + `s.id='${THEME_STYLE_ID}-prepaint';s.textContent=c.replace(/:root:root/g,':root:root:root');`
  + `document.head.appendChild(s)}}catch(e){}`

export default defineNuxtPlugin({
  name: 'theme',
  setup() {
    const { theme } = useTheme()

    useHead({
      style: [{ key: THEME_STYLE_ID, id: THEME_STYLE_ID, textContent: () => themeToCss(theme.value) }],
      script: [{ key: `${THEME_STYLE_ID}-prepaint`, innerHTML: PREPAINT_SCRIPT, tagPosition: 'head' }],
    })
  },
})
